      "joinColumn": "globalId",
      "valueColumn": "operational_carbon"
    },
    "coloredCategory": {
      "colorMap": "category10",
      "joinColumn": "globalId",
      "valueColumn": "category"
    },
    "csv": {
      "path": "$csv"
    },
    "csvMatchedNonPhysical": {
      "kind": "semi",
      "leftKey": "GlobalId",
      "rightKey": "GlobalId"
    },
    "csvNoEntity": {
      "kind": "anti",
      "leftKey": "GlobalId",
      "rightKey": "GlobalId"
    },
    "csvWithStorey": {
      "kind": "inner",
      "leftKey": "GlobalId",
      "rightKey": "GlobalId"
    },
    "entities": {
      "source": "duplex-base",
      "table": "EntityText"
    },
    "entityStorey": {
      "kind": "inner",
      "leftKey": "EntityIndex",
      "rightKey": "EntityIndex"
    },
    "instances": {
      "name": "instances"
    },
    "levelAgreement": {
      "title": "CSV rows whose Level agrees with the model's storey"
    },
    "levelCounts": {
      "aggregates": "count(*) as Rows",
      "groupBy": "Agrees"
    },
    "matchCounts": {
      "sql": "SELECT (SELECT count(*) FROM t1) AS CsvRowsWithNoEntity, (SELECT count(*) FROM t2) AS PhysicalElementsWithNoCsvRow, (SELECT count(*) FROM t3) AS CsvRowsMatchingNonPhysicalEntity"
    },
    "matchRows": {
      "limit": "0"
    },
    "model": {
      "path": "$model"
    },
    "nonPhysicalEntities": {
      "kind": "anti",
      "leftKey": "GlobalId",
      "rightKey": "globalId"
    },
    "perStorey": {
      "title": "Operational carbon per storey (CSV values, model storeys)"
    },
    "physical": {
      "aggregates": "count(*) as meshCount",
      "groupBy": "globalId"
    },
    "physicalEntities": {
      "kind": "semi",
      "leftKey": "GlobalId",
      "rightKey": "globalId"
    },
    "physicalNoCsv": {
      "kind": "anti",
      "leftKey": "GlobalId",
      "rightKey": "GlobalId"
    },
    "storeyComparison": {
      "columns": "Name, Level, StoreyName, Agrees, GlobalId",
      "title": "CSV Level against the model's storey"
    },
    "storeyOf": {
      "source": "duplex-base",
      "table": "StoreyOfElement"
    },
    "storeyOfMin": {
      "sql": "SELECT * FROM t1 QUALIFY row_number() OVER (PARTITION BY EntityIndex ORDER BY Depth) = 1"
    },
    "storeyTotals": {
      "aggregates": "count(*) as Elements, sum(operational_carbon) as TotalOperationalCarbon, avg(operational_carbon) as MeanOperationalCarbon, avg(energy_intensity) as MeanEnergyIntensity",
      "groupBy": "StoreyName"
    },
    "withStorey": {
      "limit": "0"
    }
  }
}

