// nrc-join-analytics   graph 5c1ad9610185
inputs csv: FilePath = "test-kit/analytics_dataset_with_levels.csv", model: FilePath = "{MODELS}/duplex-base.ifc";
about = view.note@1(text: "Template: joins an analytics CSV to a model by GlobalId (here the IFC viewer test kit's analytics_dataset_with_levels.csv, 268 rows, over duplex-base.ifc). Set the csv input to another CSV under the nrc sample folder and model to another IFC; the entity and storey tables come from the duplex-base database source, so another model also needs its database registered under that name. answer counts CSV rows with no entity (0), physical elements with no CSV row (21), and CSV rows on entities with no mesh (52: openings and stairs). An element that reaches several storeys gets the one with the smallest Depth, the rule nrc-enrich-run uses, so perStorey and storeyComparison count each element once; levelAgreement counts the 61 rows whose Level (often a door or window mark such as A102) is not the model's storey.");
  // Ok
csv = value.path@1(path: "$csv");
  // Ok  Text "test-kit/analytics_dataset_with_levels.csv"
analytics = rel.csv@1(path: csv.path, source: "nrc");
  // Ok  relation 268 rows x 6 cols  sha 2ed673e1a75a  plan d86be52e53af
  //   columns GlobalId:Text, Name:Text, Level:Text, operational_carbon:Number, energy_intensity:Number, category:Text
  //   [0] "2OrWItJ6zAwBNp0OUxK_l8", "M_W-Wide Flange:W310X60:W310X60:207325", "Level 1", 139.5, 27.7, "Other"
  //   [1] "2OrWItJ6zAwBNp0OUxK$8W", "M_W-Wide Flange:W410X60:W410X60:208949", "Level 1", 59.5, 25.9, "Other"
  //   [2] "2OrWItJ6zAwBNp0OUxK$Bq", "M_W-Wide Flange:W410X60:W410X60:209121", "Level 2", 95.1, 29.3, "Other"
analyticsRows = rel.materialize@1(input: analytics.relation, limit: "0");
  // Ok  table 268 rows x 6 cols  sha 2ed673e1a75a
  //   columns GlobalId:Text, Name:Text, Level:Text, operational_carbon:Number, energy_intensity:Number, category:Text
  //   [0] "2OrWItJ6zAwBNp0OUxK_l8", "M_W-Wide Flange:W310X60:W310X60:207325", "Level 1", 139.5, 27.7, "Other"
  //   [1] "2OrWItJ6zAwBNp0OUxK$8W", "M_W-Wide Flange:W410X60:W410X60:208949", "Level 1", 59.5, 25.9, "Other"
  //   [2] "2OrWItJ6zAwBNp0OUxK$Bq", "M_W-Wide Flange:W410X60:W410X60:209121", "Level 2", 95.1, 29.3, "Other"
entities = rel.table@1(source: "duplex-base", table: "EntityText");
  // Ok  relation 4721 rows x 6 cols  sha 5fc6c7198857  plan fbac43cf5e83
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
  //   [0] 77, 6413, "1Jx6Wzbs17ugoFEefHo1BC", "4835mm x 2420mm", "IFCWINDOWSTYLE", null
  //   [1] 78, 6639, "28VDfyq51BtxN68z6Brpvs", "1250mm x 2010mm", "IFCDOORSTYLE", null
  //   [2] 79, 6908, "1DUB3WxH5BFQb5h$$S4JfA", "750mm x 2200mm", "IFCWINDOWSTYLE", null
csvNoEntity = rel.join@1(left: analytics.relation, right: entities.relation, leftKey: "GlobalId", rightKey: "GlobalId", kind: "anti");
  // Ok  relation 0 rows x 6 cols  sha 6bd2a8141d22  plan cf6507388a45
  //   columns GlobalId:Text, Name:Text, Level:Text, operational_carbon:Number, energy_intensity:Number, category:Text
model = value.path@1(path: "$model");
  // Ok  Text "{MODELS}/duplex-base.ifc"
meshes = view3d.instances@1(path: model.path);
  // Ok  table 714 rows x 11 cols  sha f912cca851d5
  //   columns instanceIndex:Integer, meshId:Integer, entityId:Integer, globalId:Text, category:Text, minX:Number, minY:Number, minZ:Number, maxX:Number, maxY:Number, maxZ:Number
  //   scene 714 instances: 714 opaque, 0 faded, 0 hidden
  //   no colour columns
  //   bounds (-0.2415, -22.18, -1.55) to (9.042, 4.383, 9)
coloredCarbon = view3d.color@1(instances: meshes.instances, values: analyticsRows.table, joinColumn: "globalId", valueColumn: "operational_carbon", colorMap: "viridis");
  // Ok
  //   instances: table 714 rows x 15 cols  sha b90205255086
  //     columns instanceIndex:Integer, meshId:Integer, entityId:Integer, globalId:Text, category:Text, minX:Number, minY:Number, minZ:Number, maxX:Number, maxY:Number, maxZ:Number, r:Number, g:Number, b:Number, a:Number
  //     scene 714 instances: 714 opaque, 0 faded, 0 hidden
  //     693 coloured in 197 colours, 21 grey
  //     legend "operational_carbon" auto 14.2 to 412: bins 449 / 124 / 40 / 80
  //     bounds (-0.2415, -22.18, -1.55) to (9.042, 4.383, 9)
  //   legend: table 5 rows x 9 cols  sha 6bf9262fa5ab
  //     columns column:Text, domain:Text, role:Text, label:Text, value:Number, r:Number, g:Number, b:Number, count:Integer
  //     legend "operational_carbon" auto: 14.2, 113.7, 213.1, 312.6, 412
coloredCategory = view3d.color@1(instances: meshes.instances, values: analyticsRows.table, joinColumn: "globalId", valueColumn: "category", colorMap: "category10");
  // Ok
  //   instances: table 714 rows x 15 cols  sha 34fadff187e3
  //     columns instanceIndex:Integer, meshId:Integer, entityId:Integer, globalId:Text, category:Text, minX:Number, minY:Number, minZ:Number, maxX:Number, maxY:Number, maxZ:Number, r:Number, g:Number, b:Number, a:Number
