  //     legend "category" categorical: "Door" 124, "Finish" 13, "Floor" 20, "Other" 140, "Railing" 130, "Roof" 2, "Stair" 66, "Wall" 104, "Window" 94
  //     bounds (-0.2415, -22.18, -1.55) to (9.042, 4.383, 9)
  //   legend: table 9 rows x 9 cols  sha 8413c16661f4
  //     columns column:Text, domain:Text, role:Text, label:Text, value:Number, r:Number, g:Number, b:Number, count:Integer
  //     legend "category" categorical: category "Door" 37, category "Finish" 13, category "Floor" 20, category "Other" 64, category "Railing" 4, category "Roof" 4, category "Stair" 8, category "Wall" 72, category "Window" 46
instances = rel.fromTable@1(table: meshes.instances, name: "instances");
  // Ok  relation 714 rows x 11 cols  sha f912cca851d5  plan 68e385fef766
  //   columns instanceIndex:Integer, meshId:Integer, entityId:Integer, globalId:Text, category:Text, minX:Number, minY:Number, minZ:Number, maxX:Number, maxY:Number, maxZ:Number
  //   scene 714 instances: 714 opaque, 0 faded, 0 hidden
  //   no colour columns
  //   bounds (-0.2415, -22.18, -1.55) to (9.042, 4.383, 9)
physical = rel.aggregate@1(input: instances.relation, groupBy: "globalId", aggregates: "count(*) as meshCount");
  // Ok  relation 237 rows x 2 cols  sha a82986dd9677  plan f772f89fd074
  //   columns globalId:Text, meshCount:Integer
  //   [0] "01KzA4SPn5IOODwLEb5RNY", 1
  //   [1] "0BTBFw6f90Nfh9rP1dlXr$", 1
  //   [2] "0BTBFw6f90Nfh9rP1dlXr2", 1
nonPhysicalEntities = rel.join@1(left: entities.relation, right: physical.relation, leftKey: "GlobalId", rightKey: "globalId", kind: "anti");
  // Ok  relation 4484 rows x 6 cols  sha 978881432346  plan fee6227021b1
  //   columns EntityIndex:Integer, StepId:Integer, GlobalId:Text, Name:Text, Category:Text, Type:Text
  //   [0] 77, 6413, "1Jx6Wzbs17ugoFEefHo1BC", "4835mm x 2420mm", "IFCWINDOWSTYLE", null
