csvMatchedNonPhysical = rel.join@1(left: analytics.relation, right: nonPhysicalEntities.relation, leftKey: "GlobalId", rightKey: "GlobalId", kind: "semi");
  // Ok  relation 52 rows x 6 cols  sha f1ec4ac60c06  plan b2ede90dd9d9
